def seg(i, les, o, sim, t, teach, warn, exq, exa, alt, before, after, mn=10):
    S.append({"i": i, "les": les, "o": o, "min": mn, "sim": sim, "t": t, "fig": "", "teach": teach, "warn": warn,
              "ex": {"q": exq, "a": exa}, "alt": alt, "before": before, "after": [{"u": a[0], "t": a[1], "x": a[2]} for a in after]})

seg(1, 1, 1, "kzgroup", "لماذا نُصنّف ؟ وكيف تتكوّن المجموعة ؟",
 "<b>علم التصنيف</b> " + L("Taxonomy") + " من أقدم العلوم ، ويقوم على <b>تصنيف الكائنات الحيّة في مجموعات بحسب صفاتها ؛ لتسهيل دراستها</b> . والدافع إليه <b>التنوّع الكبير</b> للكائنات الحيّة ، فأطلق العلماء على كلّ كائن اسمًا خاصًّا ، وجمعوا الكائنات في مجموعات بحسب <b>صفاتها المشتركة</b>.\n"
 "والمجموعة التصنيفية لها خاصّيتان تُبنى عليهما الوحدة كلّها :\n"
 "<b>أفرادها يشتركون في صفة أو أكثر</b> هي معيار المجموعة ؛ فإن تغيّر المعيار تغيّرت المجموعات نفسها.\n"
 "<b>المجموعة الكبيرة تنقسم إلى مجموعات أصغر</b> أفرادها أكثر تشابهًا ، وهذه هي <b>الأقسام الرئيسة</b> : نطاقات ، ثمّ ممالك ، ثمّ مستويات حتّى النوع.\n"
 "مثال : لو جمعتَ الحيوانات بحسب <b>مكان معيشتها</b> لوقع الحوت مع السمكة ، ولو جمعتها بحسب <b>طريقة حركتها</b> لوقع الطائر مع الخفّاش . فالسؤال الأوّل أمام أيّ تصنيف : <b>ما المعيار ؟</b>\n"
 "وأهمّية التصنيف : يُسهّل دراسة ملايين الكائنات ، ويكشف ما بينها من تشابه واختلاف ، ويُوحّد أسماءها بين العلماء.",
 "لا تظنّ أنّ للكائن مجموعة واحدة « طبيعية » مهما اختلف المعيار ؛ فالمجموعات <b>تتبع المعيار المختار</b> ، ولهذا تطوّرت أنظمة التصنيف . ولا تجعل الغاية من التصنيف حفظ الأسماء ؛ الغاية <b>تسهيل الدراسة</b>.",
 "صنّف الكائنات الآتية مرّة بحسب مكان المعيشة ، ومرّة بحسب الحجم ( للنباتات ) : حمامة ، سمكة ، قطّة ، نخلة ، نعناع ، شجيرة الورد.",
 "<b>بحسب مكان المعيشة</b> ( للحيوانات ) : هوائية : الحمامة · مائية : السمكة · برّية : القطّة.\n<b>بحسب الحجم</b> ( للنباتات ) : أشجار : النخلة · شجيرات : الورد · أعشاب : النعناع.\n<b>الاستنتاج</b> : المجموعات تتبع المعيار المختار ، وهذا تصنيف أرسطو نفسه.",
 "التصنيف يشبه <b>ترتيب مكتبة</b> : تستطيع ترتيب الكتب بحسب اللون أو الحجم أو الموضوع ، وكلّ ترتيب يُنتج رفوفًا مختلفة . والمكتبة المفيدة هي التي يُرتَّب فيها الكتاب بموضوعه ، ثمّ بفرع الموضوع ، ثمّ بمؤلّفه.",
 "تعرف من دروسك السابقة أنّ الكائنات الحيّة متنوّعة تنوّعًا كبيرًا.",
 [("b10u3", "المقطع الثاني من هذه الوحدة", "كيف تغيّر المعيار عبر التاريخ : من الحجم ومكان المعيشة إلى المادّة الوراثية."),
  ("b10u1", "نظرية التطوّر — أحياء العاشر", "التشابه الذي يجمع الكائنات في مجموعة واحدة يدلّ على قرابتها.")])

seg(2, 1, 2, "kzhist", "من أرسطو إلى ووز : تطوّر أنظمة التصنيف",
 "مرّ التصنيف بمراحل ، وفي كلّ مرحلة <b>معيار</b> جديد :\n"
 "<b>أرسطو</b> " + L("Aristotle") + " ( 384 – 322 ق.م ) : <b>أوّل من صنّف</b> ؛ النباتات بحسب <b>حجومها</b> : أشجار وشجيرات وأعشاب ، والحيوانات بحسب <b>مكان معيشتها</b> : هوائية وبرّية ومائية.\n"
 "<b>الجاحظ والقزوينيّ</b> من علماء المسلمين : صنّفوا الحيوانات بحسب <b>طريقة حركتها</b> . ولـ<b>ابن البيطار</b> والقزوينيّ إسهامات في التصنيف وفي إيجاد الأدوية لعلاج الأمراض.\n"
 "<b>كارلوس لينيوس</b> " + L("Carolus Linnaeus") + " : <b>أوّل من استعمل النظام الهرميّ</b> بحسب <b>أوجه التشابه والاختلاف</b> ، ووضع أُسس التصنيف العلميّ الحديث و<b>نظام التسمية الثنائية</b>.\n"
 "<b>روبرت وتكر</b> " + L("Robert Whittaker") + " ( <b>1969 م</b> ) : قسّم الكائنات إلى <b>خمس ممالك</b> : البدائيات ، والطلائعيات ، والفطريات ، والنباتات ، والحيوانات ، بحسب <b>صفات الخلية</b> : أشكالها ، وعضيّاتها ، ونمط تغذيتها ( ذاتية ، امتصاصية ، التهامية ) ، ووجود الغلاف النوويّ ، والدراسات الوراثية ، ودراسات المِجهر الإلكترونيّ.\n"
 "<b>كارل ووز</b> " + L("Carl Woese") + " : بـ<b>مقارنة المادّة الوراثية</b> قسّم البدائيات إلى <b>بكتيريا وأثريات</b> ، ورتّب الكائنات في <b>ثلاثة نطاقات</b>.\n"
 "لاحظ أنّ المعيار ينتقل من <b>الشكل الظاهر</b> إلى <b>الخلية</b> ثمّ إلى <b>المادّة الوراثية</b> ، كلّما تطوّرت الأدوات.",
 "لا تنسب النطاقات الثلاثة إلى وتكر ؛ <b>وتكر صاحب الممالك الخمس ( 1969 م )</b> ، و<b>ووز صاحب النطاقات الثلاثة</b> . ولا تجعل أرسطو صاحب النظام الهرميّ ؛ أوّل من استعمله <b>لينيوس</b>.",
 "اذكر المعيار الذي اعتمده كلّ من : أرسطو في تصنيف الحيوانات ، والجاحظ ، ووتكر ، وووز.",
 "<b>أرسطو</b> : مكان المعيشة ( هوائية ، برّية ، مائية ).\n<b>الجاحظ</b> : طريقة الحركة.\n<b>وتكر</b> : صفات الخلية ( أشكالها ، عضيّاتها ، نمط تغذيتها ، الغلاف النوويّ ، الدراسات الوراثية ، المجهر الإلكترونيّ ).\n<b>ووز</b> : مقارنة المادّة الوراثية.",
 "تخيّل أنّك تصف الناس : أوّلًا بالطول ( أرسطو ) ، ثمّ بطريقة المشي ( الجاحظ ) ، ثمّ بأوجه الشبه الكثيرة معًا ( لينيوس ) ، ثمّ بتحليل الدم ( وتكر ) ، ثمّ بفحص الحمض النوويّ ( ووز ) . كلّ أداة أدقّ تكشف قرابة لم تكن تُرى.",
 "يُبنى على المقطع الأول : المجموعات تتبع المعيار ، وهنا قصّة تغيّر المعيار.",
 [("b10u3", "المقطع الثالث من هذه الوحدة", "النظام الهرميّ الذي بدأه لينيوس صار سبعة مستويات."),
  ("b10u3", "المقطع الخامس من هذه الوحدة", "ما صنعه ووز : نطاقان للبدائيات ونطاق لحقيقيات النَّوى.")])

seg(3, 1, 3, "kzlevels", "مستويات التصنيف السبعة",
 "يقوم النظام الهرميّ على <b>تجميع الأنواع في فئات أشمل</b> بحسب أوجه التشابه والاختلاف ، وطُوِّر بعد لينيوس ليشمل <b>سبعة مستويات</b> " + L("Taxonomic Levels") + ".\n"
 "يبدأ بـ<b>النوع</b> " + L("Species") + " ( الوحدة الأساسية وأخصّ المستويات ) ، ثمّ <b>الجنس</b> " + L("Genus") + " يجمع الأنواع المتشابهة كثيرًا ، ثمّ <b>العائلة</b> ، ثمّ <b>الرتبة</b> ، ثمّ <b>الصفّ</b> ، ثمّ <b>القبيلة</b> ، ثمّ <b>المملكة</b>.\n"
 "فالترتيب <b>من الأعمّ إلى الأخصّ</b> : مملكة ← قبيلة ← صفّ ← رتبة ← عائلة ← جنس ← نوع.\n"
 "مثال الكتاب : <b>الورد الفرنسيّ</b> ( الشكل ( 1 ) ) : المملكة " + L("Plantae") + " ، القبيلة " + L("Angiospermae") + " ، الصفّ " + L("Dicotyledonae") + " ، الرتبة " + L("Rosales") + " ، العائلة " + L("Rosaceae") + " ، الجنس " + L("Rosa") + " ، النوع " + L("gallica") + ".\n"
 "<b>قاعدتان تحسمان الأسئلة</b> : كلّما نزلنا من المملكة إلى النوع <b>قلّ عدد الأفراد وزاد التشابه بينهم</b> ، وكلّما صعدنا زاد العدد وقلّ التشابه . و<b>الاسم العلميّ يُؤخذ من آخر مستويين</b> : الجنس + النوع ، فالورد الفرنسيّ " + L("Rosa gallica") + ".\n"
 "والكتاب يُسمّي المستوى الثاني <b>القبيلة</b> " + L("Phylum") + ".",
 "لا تعكس القاعدة : التشابه <b>يزداد كلّما نزلنا</b> نحو النوع ، لا كلّما صعدنا . ولا تخلط عدد المستويات ( <b>سبعة</b> ) بعدد النطاقات ( <b>ثلاثة</b> ) ولا بعدد الممالك في حقيقيات النَّوى ( <b>أربع</b> ).",
 "ينتمي الإنسان " + L("Homo sapiens") + " إلى عائلة " + L("Hominidae") + " وقبيلة " + L("Chordata") + " ورتبة " + L("Primates") + " وصفّ " + L("Mammalia") + " . رتّب تصنيفه من الأعمّ إلى الأخصّ.",
 "المملكة : " + L("Animalia") + "\nالقبيلة : " + L("Chordata") + "\nالصفّ : " + L("Mammalia") + "\nالرتبة : " + L("Primates") + "\nالعائلة : " + L("Hominidae") + "\nالجنس : " + L("Homo") + " ، والنوع : " + L("sapiens") + " ، والاسم العلميّ من آخر مستويين : " + L("Homo sapiens") + ".",
 "المستويات كـ<b>العنوان البريديّ</b> : الدولة ( مملكة ) ← المحافظة ← المدينة ← الحيّ ← الشارع ← البناية ( جنس ) ← الشقّة ( نوع ) . كلّما نزلت قلّ عدد الساكنين وزاد ما يجمعهم . وجملة تساعد على حفظ الترتيب : <b>م</b>ملكة <b>ق</b>بيلة <b>ص</b>فّ <b>ر</b>تبة <b>ع</b>ائلة <b>ج</b>نس <b>ن</b>وع.",
 "يُبنى على المقطع الثاني : النظام الهرميّ الذي بدأه لينيوس.",
 [("b10u3", "المقطع الرابع من هذه الوحدة", "آخر مستويين ( الجنس والنوع ) هما الاسم العلميّ نفسه."),
  ("b10u1", "نظرية التطوّر — أحياء العاشر", "النوع الذي تبدأ به المستويات هو الوحدة التي يحدث فيها التطوّر.")])

seg(4, 1, 4, "kzname", "الاسم العلميّ : التسمية الثنائية",
 "وضع <b>لينيوس</b> نظام <b>التسمية الثنائية</b> " + L("Binomial Nomenclature") + " ليستعمل العلماء كافّة <b>اسمًا موحّدًا</b> للكائن هو <b>الاسم العلميّ</b> " + L("Scientific Name") + " ، وقواعده أربع :\n"
 "<b>اللغة</b> : اللاتينية.\n"
 "<b>كلمتان</b> : الأولى تدلّ على <b>الجنس</b> ، والثانية على <b>النوع</b>.\n"
 "<b>الحروف</b> : الحرف الأوّل من الجنس <b>كبير</b> ، والحرف الأوّل من النوع <b>صغير</b>.\n"
 "<b>الخطّ</b> : تُكتب الكلمتان <b>بخطّ مائل</b> ، أو يُوضع <b>خطّ تحت كلّ كلمة على حِدة</b>.\n"
 "أمثلة الكتاب : الإنسان " + L("Homo sapiens") + " ، الزيتون " + L("Olea europaea") + " ، نحل العسل " + L("Apis mellifera") + " ، الشيح " + L("Artemisia herba-alba") + ".\n"
 "ولماذا اللاتينية ؟ لأنّها <b>لغة ثابتة لا تتغيّر مفرداتها</b> . ونبات الميرمية ( الشكل ( 3 ) ) له في البلدان العربية أسماء شائعة كثيرة : القصعين والعيزقان ولسان الأيّل ، واسمه العلميّ <b>واحد</b> : " + L("Salvia officinalis") + ".\n"
 "وفي أسئلة التصويب افحص الثلاثة بالترتيب : <b>هل الجنس بحرف كبير ؟ هل النوع بحرف صغير ؟ هل الكتابة مائلة أو تحتها خطّ ؟</b>",
 "أكثر الأخطاء : كتابة النوع بحرف كبير ( " + L("Homo Sapiens") + " خطأ ) ، أو الجنس بحرف صغير ( " + L("homo sapiens") + " خطأ ) . والخطّ المائل أو الخطّ تحت الاسم <b>جزء من القاعدة</b> لا زينة.",
 "ينتمي نوع الأسد " + L("leo") + " ونوع النمر " + L("tigris") + " إلى الجنس " + L("Panthera") + " . اكتب الاسم العلميّ لكلّ منهما ، وصوّب الاسم " + L("Artemisia Herba-alba") + ".",
 "<b>الأسد</b> : " + L("Panthera leo") + " · <b>النمر</b> : " + L("Panthera tigris") + " ، بخطّ مائل أو بخطّ تحت كلّ كلمة.\n<b>التصويب</b> : " + L("Artemisia herba-alba") + " ؛ فالحرف الأوّل من النوع يُكتب صغيرًا.",
 "الاسم العلميّ كـ<b>الاسم الرباعيّ مقلوبًا إلى ثنائيّ</b> : اسم العائلة الكبيرة أوّلًا بحرف كبير ( الجنس ) ، ثمّ اسم الفرد ( النوع ) . وكما لا يتغيّر اسمك في جواز السفر وإن ناداك كلّ بلد بلقب ، لا يتغيّر الاسم العلميّ وإن تعدّدت الأسماء الشائعة.",
 "يُبنى على المقطع الثالث : الجنس والنوع آخر مستويين في السلّم.",
 [("b10u3", "المقطع الخامس من هذه الوحدة", "الاسم العلميّ أخصّ ما في التصنيف ، والنطاق أعمّه."),
  ("b10u3", "المقطع الحادي عشر من هذه الوحدة", "ستكتب أسماء بكتيريا بالقاعدة نفسها : " + L("Clostridium tetani") + ".")])

seg(5, 1, 5, "kzdomain", "النطاقات الثلاثة والممالك الأربع",
 "<b>وتكر ( 1969 م )</b> قسّم الكائنات إلى خمس ممالك ، أولاها <b>البدائيات</b> وتشمل جميع الكائنات <b>بدائية النواة</b>.\n"
 "ثمّ قارن <b>ووز</b> المادّة الوراثية لمجموعات من البدائيات ، فوجدها <b>مجموعتين مختلفتين</b> : <b>البكتيريا</b> " + L("Bacteria") + " و<b>الأثريات</b> " + L("Archaea") + " ( البكتيريا القديمة أو العتائق ) ، فرُتّبت الكائنات في ثلاثة <b>نطاقات</b> " + L("Domain") + " ( الشكل ( 2 ) ) — والنطاق <b>أعلى مستوى</b> في التصنيف الحديث :\n"
 "<b>نطاق البكتيريا</b> : بدائية النَّوى.\n"
 "<b>نطاق الأثريات</b> : بدائية النَّوى.\n"
 "<b>نطاق حقيقيات النَّوى</b> " + L("Eukarya") + " : وفيه <b>أربع ممالك</b> : <b>الطلائعيات ، والفطريات ، والنباتات ، والحيوانات</b>.\n"
 "فما الذي حدث للممالك الخمس ؟ مملكة البدائيات <b>انقسمت نطاقين</b> ، والممالك الأربع الباقية <b>اجتمعت في نطاق واحد</b> . ولتحديد مكان أيّ كائن اسأل : <b>هل خلاياه حقيقية النَّوى ؟</b> لا ← بكتيريا أو أثريات . نعم ← إحدى الممالك الأربع.",
 "لا تقل إنّ التصنيف الحديث <b>خمس ممالك</b> فقط ؛ فالممالك الأربع تقع <b>داخل نطاق حقيقيات النَّوى</b> ، والبدائيات صارت نطاقين . ولا تضع الفطريات أو الطلائعيات خارج نطاق حقيقيات النَّوى.",
 "حدّد النطاق لكلّ ممّا يأتي : الأميبا ، فطر المشروم ، بكتيريا القولون ، كائن بدائيّ النواة يعيش في الينابيع الساخنة ، شجرة الزيتون.",
 "<b>الأميبا</b> : حقيقيات النَّوى ( مملكة الطلائعيات ).\n<b>المشروم</b> : حقيقيات النَّوى ( مملكة الفطريات ).\n<b>بكتيريا القولون</b> : نطاق البكتيريا.\n<b>كائن الينابيع الساخنة</b> : نطاق الأثريات ( بدائيّ النواة في بيئة قاسية ).\n<b>الزيتون</b> : حقيقيات النَّوى ( مملكة النباتات ).",
 "تخيّل <b>مبنى بثلاثة مداخل</b> : مدخلان صغيران لغرفتين ( البكتيريا والأثريات ) ، ومدخل كبير يفضي إلى ممرّ فيه أربعة أجنحة ( الطلائعيات والفطريات والنباتات والحيوانات ).",
 "يُبنى على المقطع الثاني : معيار ووز ( المادّة الوراثية ) هو الذي فصل البكتيريا عن الأثريات.",
 [("b10u3", "المقطع السادس من هذه الوحدة", "ما الفرق بين البكتيريا والأثريات وكلاهما بدائيّ النواة ؟"),
  ("b9u2", "الخليّة وعمليّاتها الحيويّة — أحياء التاسع", "الخلية بدائية النواة وحقيقية النواة اللتان درستهما هما أساس النطاقات.")])

seg(6, 2, 6, "kzarch", "البكتيريا والأثريات : تشابه كثير وأربعة فروق",
 "<b>ما يشتركان فيه</b> : كلاهما <b>بدائيّ النَّوى</b> ؛ خلية صغيرة جدًّا لها <b>جدار خلويّ وغشاء بلازميّ</b> ، وسيتوبلازم <b>يخلو من النواة والعضيّات الغشائية</b> ، والمادّة الوراثية <b>شريط مزدوج حلقيّ</b> محاط بالسيتوبلازم ، وقد تحتوي <b>البلازميد</b> ، ويتحرّكان <b>بالانزلاق أو بالأسواط</b>.\n"
 "<b>الفروق الأربعة</b> :\n"
 "<b>الجدار الخلويّ</b> : في البكتيريا <b>يحتوي الببتيدوغلايكان</b> " + L("Peptidoglycan") + " ، وفي الأثريات <b>لا يحتويه</b>.\n"
 "<b>الغشاء البلازميّ</b> : يختلف في <b>تركيبه الكيميائيّ</b>.\n"
 "<b>البيئة</b> : البكتيريا في بيئات متنوّعة ، والأثريات في <b>بيئات قاسية</b> : الينابيع الساخنة ، والمياه المالحة مثل <b>البحر الميت</b>.\n"
 "<b>مصادر الطاقة</b> : تستعمل الأثريات <b>الأمونيا وغاز الهيدروجين والمركّبات العضوية</b> ، والتي تعيش في البيئات المالحة <b>أشعّة الشمس</b> ، وبعضها <b>يُثبّت ثاني أكسيد الكربون</b>.\n"
 "وتُقسَّم البكتيريا <b>بحسب الشكل</b> ، والأثريات <b>بحسب البيئة</b> : المحبّة للحرارة ، والمحبّة للملوحة ، والمنتجة للميثان . ولعيش الأثريات في البيئات القاسية <b>رجّح العلماء وجودها منذ نشأة الحياة</b> . ويُفيد الببتيدوغلايكان في تصنيف البكتيريا بـ<b>صبغة غرام</b> ، وهذا يُساعد على تحديد البكتيريا المُسبّبة للمرض و<b>اختيار المضادّ الحيويّ المناسب</b>.",
 "لا تنسب الببتيدوغلايكان إلى الأثريات ؛ هو في <b>جدار البكتيريا وحدها</b> . ولا تجعل الأثريات حقيقية النَّوى لأنّها مختلفة عن البكتيريا ؛ فكلاهما <b>بدائيّ النَّوى</b> . والقاعدة : احفظ الفروق الأربعة ، وما عداها مشترك.",
 "فسّر : تُصنَّف البكتيريا والأثريات ضمن الكائنات بدائية النَّوى مع أنّهما في نطاقين مختلفين.",
 "<b>سبب الجمع</b> : كلاهما خلية صغيرة جدًّا بلا نواة ولا عضيّات غشائية ، والمادّة الوراثية شريط مزدوج حلقيّ محاط بالسيتوبلازم مباشرةً ، وهذا تعريف بدائيّ النَّوى.\n<b>سبب الفصل</b> : الاختلاف في الجدار ( الببتيدوغلايكان في البكتيريا وحدها ) والغشاء البلازميّ والبيئة ومصادر الطاقة ، وكشفته مقارنة المادّة الوراثية.",
 "البكتيريا والأثريات كـ<b>توأمين متشابهين في الملامح</b> ( الشكل الخارجيّ وبنية الخلية ) ، مختلفين في <b>بصمة الإصبع</b> ( الجدار والغشاء ) و<b>مكان السكن</b> ( الأثريات تسكن الأماكن القاسية ) و<b>نوع الطعام</b> ( مصادر الطاقة ).",
 "يُبنى على المقطع الخامس : نطاقا البدائيات ، وهنا ما يجمعهما وما يفرّقهما.",
 [("b10u3", "المقطع السابع من هذه الوحدة", "أجزاء الخلية البكتيرية بالتفصيل : من المحفظة إلى الأسواط."),
  ("s8u4", "علوم الأرض والبيئة — علوم الثامن", "البحر الميت الذي تعيش فيه الأثريات المحبّة للملوحة من بيئات الأردنّ.")])

seg(7, 2, 7, "kzcell", "تركيب الخلية البكتيرية",
 "في الشكل ( 6 ) أجزاء الخلية البكتيرية من الخارج إلى الداخل :\n"
 "<b>المحفظة</b> : غلاف خارجيّ يحيط بالجدار الخلويّ.\n"
 "<b>الجدار الخلويّ</b> : يحمي الخلية ويحدّد شكلها ، وفيه <b>الببتيدوغلايكان</b>.\n"
 "<b>الغشاء البلازميّ</b> : يحيط بالسيتوبلازم وينظّم دخول المواد وخروجها.\n"
 "<b>السيتوبلازم</b> : الوسط الذي تسبح فيه مكوّنات الخلية.\n"
 "<b>المادّة الوراثية</b> " + L("DNA") + " : <b>شريط مزدوج حلقيّ</b> في السيتوبلازم مباشرةً ؛ لعدم وجود نواة.\n"
 "<b>البلازميد</b> " + L("Plasmid") + " : قطعة صغيرة حلقية من المادّة الوراثية <b>منفصلة</b> عن المادّة الوراثية الرئيسة.\n"
 "<b>الرايبوسومات</b> : مواقع بناء البروتين.\n"
 "<b>الأسواط</b> : تراكيب تتحرّك بها الخلية.\n"
 "ولاحظ ما <b>لا يوجد</b> : لا نواة ، ولا عضيّات غشائية كالميتوكندريا وجهاز غولجي ؛ والرايبوسومات ليست غشائية ولذلك توجد . والبلازميد صغير لكنّه مهمّ : سنرى أنّه ينتقل بين الخلايا فيُكسبها صفات جديدة.",
 "لا تخلط <b>البلازميد</b> بالمادّة الوراثية الرئيسة ؛ فهو قطعة صغيرة <b>منفصلة</b> عنها . ولا تضع المادّة الوراثية داخل نواة ؛ فالبكتيريا <b>بلا نواة</b> . ولا تخلط المحفظة ( خارج الجدار ) بالجدار نفسه.",
 "خلية بكتيرية فقدت جدارها الخلويّ . ما الوظيفتان اللتان تتأثّران مباشرةً ؟ وأيّ مكوّن من جدارها يُستعمل في تصنيفها ؟",
 "<b>الوظيفتان</b> : حماية الخلية ، وتحديد شكلها.\n<b>المكوّن</b> : الببتيدوغلايكان ؛ وبه تُصنَّف البكتيريا بناءً على صبغة غرام ، وهذا يساعد على اختيار المضادّ الحيويّ المناسب.",
 "الخلية البكتيرية <b>كيس مُحكم بثلاث طبقات</b> ( محفظة ، جدار ، غشاء ) ، في داخله <b>حبل ملفوف</b> ( الكروموسوم الحلقيّ ) و<b>خاتم صغير</b> ( البلازميد ) و<b>آلات صغيرة</b> لصنع البروتين ( الرايبوسومات ) ، وفي خارجه <b>مجاديف</b> ( الأسواط ).",
 "يُبنى على المقطع السادس : الجدار والغشاء اللذان يفرّقان البكتيريا عن الأثريات.",
 [("b10u3", "المقطع العاشر من هذه الوحدة", "البلازميد هو ما ينتقل في الاقتران."),
  ("b9u2", "الخليّة وعمليّاتها الحيويّة — أحياء التاسع", "قارن : الخلية الحيوانية والنباتية فيهما نواة وعضيّات غشائية لا توجد هنا.")])

seg(8, 2, 7, "kzshape", "أشكال البكتيريا وهيئات وجودها وحجمها",
 "للبكتيريا <b>ثلاثة أشكال رئيسة</b> هي الأكثر انتشارًا ، وتُسمّى بحسبها ( الشكل ( 5 ) ) :\n"
 "<b>الكروية</b> " + L("Coccus") + " · <b>العصوية</b> " + L("Bacillus") + " · <b>الحلزونية</b> " + L("Spirillum") + ".\n"
 "و<b>هيئات وجودها</b> أربع : <b>منفردة</b> ، أو <b>ثنائيات</b> ، أو <b>سلاسل</b> ، أو <b>عنقودية</b>.\n"
 "فاسم الهيئة يُركَّب من الشكل والتجمّع : كروية عنقودية ، عصوية في سلاسل ، كروية ثنائية ... وهكذا.\n"
 "<b>وحجمها</b> صغير جدًّا يُقاس بالميكرومتر ، والفيروس أصغر منها ويُقاس بالنانومتر . ولمقارنة طولين : <b>وحّد الوحدة أوّلًا ثمّ اقسم</b> :\n"
 "القاعدة : " + L("1 µm = 1000 nm") + ".\n"
 "مثال الكتاب : خلية بكتيريا طولها " + L("6 µm") + " وفيروس طوله " + L("150 nm") + " ، فـ" + L("6 µm = 6000 nm") + " ثمّ " + L("6000 ÷ 150 = 40") + " ، أي <b>40 مرّة</b>.\n"
 "والخطأ الشائع قسمة 6 على 150 مباشرةً ؛ فالناتج حينئذٍ أصغر من واحد ، أي أنّ البكتيريا « أصغر » من الفيروس ، وهذا يكشف الخطأ وحده.",
 "لا تخلط <b>الشكل</b> ( كروية ، عصوية ، حلزونية ) بـ<b>الهيئة</b> ( منفردة ، ثنائيات ، سلاسل ، عنقودية ) . ولا تقسم قبل توحيد الوحدتين.",
 "طول خلية بكتيرية 3 µm ، وطول فيروس 100 nm . كم مرّة يزيد طول البكتيريا على طول الفيروس ؟",
 "<b>توحيد الوحدة</b> : " + L("3 µm = 3 × 1000 = 3000 nm") + ".\n<b>القسمة</b> : " + L("3000 ÷ 100 = 30") + ".\n<b>الجواب</b> : 30 مرّة.",
 "الشكل كـ<b>شكل الخرزة</b> ( كرة ، أنبوب ، لولب ) ، والهيئة كـ<b>طريقة نظمها</b> : خرزة وحدها ، أو خرزتان ، أو مسبحة ( سلسلة ) ، أو عنقود عنب.",
 "يُبنى على المقطع السابع : الجدار الخلويّ هو الذي يُحدّد الشكل.",
 [("b10u2", "الفيروسات والفيرويدات والبريونات — أحياء العاشر", "الفيروس الذي قارنت به حجم البكتيريا ليس خلية أصلًا."),
  ("p9u1", "القياس — فيزياء التاسع", "البادئتان ميكرو ونانو اللتان تعلّمتهما تجعلان التحويل سهلًا.")])

seg(9, 2, 8, "kzfiss", "الانشطار الثنائيّ",
 "تتكاثر البكتيريا <b>لاجنسيًّا</b> بـ<b>الانشطار الثنائيّ</b> " + L("Binary Fission") + " ، ومراحله في الشكل ( 7 ) :\n"
 "<b>1</b> — <b>يتضاعف</b> الحمض النوويّ المكوّن للكروموسوم الحلقيّ ، فيتكوّن كروموسوم حلقيّ جديد ، ويزداد حجم الخلية ، وتتحرّك نسخة إلى كلّ طرف.\n"
 "<b>2</b> — <b>ينغمد الغشاء البلازميّ</b> ( يتخصّر ) في المنتصف ، وتترسّب مكوّنات الجدار الخلويّ في الوسط.\n"
 "<b>3</b> — <b>تنفصل</b> الخليتان بجدار خلويّ جديد.\n"
 "<b>4</b> — <b>خليتان متطابقتان</b>.\n"
 "ولأنّ الخلية تنقسم إلى اثنتين ، فكلّ انشطار <b>يُضاعف العدد</b> : 1 ← 2 ← 4 ← 8 … ؛ أي بعد " + L("n") + " مرّة من الانشطار يصير العدد " + L("2ⁿ") + " . وهذا يفسّر سرعة تكاثر البكتيريا حين تتوفّر الظروف.\n"
 "والخليتان الناتجتان <b>متطابقتان</b> لأنّ كلًّا منهما أخذت نسخة من الكروموسوم المضاعَف ، ولا اتّحاد فيه بين خليتين.",
 "لا تعدّ الانشطار الثنائيّ تكاثرًا جنسيًّا ؛ هو <b>لاجنسيّ</b> ينتج خليتين <b>متطابقتين</b> . ولا ترتّب الخطوات بالعكس : <b>التضاعف أوّلًا</b> ثمّ التخصّر ثمّ الانفصال . ولا تحسب عدد الخلايا بالجمع ( 3 مرّات = 6 ) ؛ العدد <b>يتضاعف</b> ( 3 مرّات = 8 ).",
 "خلية بكتيرية انشطرت أربع مرّات متتالية . كم خلية تنتج ؟ وما العلاقة بينها في الصفات الوراثية ؟",
 "<b>العدد</b> : " + L("2⁴ = 16") + " خلية ( 1 ← 2 ← 4 ← 8 ← 16 ).\n<b>العلاقة</b> : متطابقة ؛ لأنّ الانشطار تكاثر لاجنسيّ تأخذ فيه كلّ خلية نسخة من الكروموسوم المضاعَف.",
 "الانشطار كـ<b>تصوير ورقة ثمّ قصّها نصفين</b> : تُنسَخ الورقة ( التضاعف ) ، وتُوضع كلّ نسخة في طرف ، ثمّ يُطوى الوسط ويُقصّ ( التخصّر والجدار الجديد ) ، فتخرج نسختان متطابقتان.",
 "يُبنى على المقطع السابع : الكروموسوم الحلقيّ والغشاء والجدار هي ما يتحرّك في الانشطار.",
 [("b10u3", "المقطع العاشر من هذه الوحدة", "الانشطار يُعطي نسخًا متطابقة ، فمن أين تأتي الصفات الجديدة ؟ من الانتقال الجينيّ."),
  ("b9u2", "الخليّة وعمليّاتها الحيويّة — أحياء التاسع", "الانقسام المتساوي الذي درسته يُنتج أيضًا خليتين متطابقتين ، لكن بخطوات أعقد.")])

seg(10, 2, 8, "kzgene", "الانتقال الجينيّ : اقتران وتحوّل ونقل",
 "تنتقل المادّة الوراثية بين الخلايا البكتيرية فـ<b>تكتسب صفات جديدة</b> ، بثلاث طرائق :\n"
 "<b>الاقتران</b> " + L("Conjugation") + " ( الشكل ( 8 ) ) : تمتدّ <b>شعيرة جنسية</b> من الخلية <b>المُعطية</b> حتّى ترتبط بالمستقبلات البروتينية على سطح الخلية <b>المُستقبِلة</b> فيتكوّن <b>جسر اقتران</b> ، وتُنقل <b>نسخة من البلازميد</b> ، ثمّ يتضاعف البلازميد في الخليتين فتنفصلان وقد <b>صارتا معطيتين معًا</b>.\n"
 "<b>التحوّل</b> " + L("Transformation") + " ( الشكل ( 9 ) ) : قطعة " + L("DNA") + " من <b>البيئة المحيطة</b> — غالبًا من <b>خلية بكتيريا ميتة</b> — ترتبط بالخلية المستقبِلة ، فتنقلها إلى داخلها عن طريق <b>الغشاء البلازميّ</b> ، ثمّ <b>تندمج</b> في حمضها النوويّ.\n"
 "<b>النقل</b> " + L("Transduction") + " ( الشكل ( 10 ) ) : <b>فيروس آكل البكتيريا</b> يحمل جزءًا من " + L("DNA") + " خلية بكتيرية ، فإذا هاجم خلية جديدة <b>نقل إليها</b> هذا الجزء فيندمج في مادّتها الوراثية.\n"
 "ولتمييزها اسأل : <b>من أين جاءت المادّة الوراثية ؟ وما الوسيط ؟</b> خلية حيّة عبر جسر ← اقتران . البيئة ( بكتيريا ميتة ) بلا وسيط ← تحوّل . فيروس ← نقل.\n"
 "ولاحظ أنّ الاقتران <b>ليس تكاثرًا</b> : لا يزيد عدد الخلايا ، بل تتغيّر صفاتها.",
 "لا تخلط <b>التحوّل</b> ( " + L("DNA") + " من البيئة ) بـ<b>النقل</b> ( " + L("DNA") + " يحمله فيروس ) . ولا تعدّ الاقتران تكاثرًا ؛ فهو انتقال جينيّ <b>لا يزيد عدد الخلايا</b> . وما ينتقل في الاقتران <b>نسخة من البلازميد</b> لا الكروموسوم.",
 "قارن بين التحوّل والنقل من حيث مصدر المادّة الوراثية والوسيط.",
 "<b>التحوّل</b> : المصدر البيئة المحيطة ( غالبًا بكتيريا ميتة ) ، وتدخل عبر الغشاء البلازميّ بلا وسيط حيّ.\n<b>النقل</b> : المصدر خلية بكتيرية أخرى ، والوسيط فيروس آكل البكتيريا.\n<b>الاتفاق</b> : يندمج الجزء المنقول في مادّة الخلية المستقبِلة فتنشأ صفات جديدة.",
 "ثلاث طرائق لوصول <b>وصفة طبخ</b> إليك : جارك يُعطيك نسخة يدًا بيد عبر الشبّاك ( اقتران ) ، أو تجد ورقة وصفة ملقاة في الشارع فتلتقطها ( تحوّل ) ، أو يحملها إليك ساعي بريد ( النقل بالفيروس ).",
 "يُبنى على المقطع التاسع : الانشطار يُنتج نسخًا متطابقة ، والصفات الجديدة تأتي من هنا.",
 [("b10u3", "المقطع الثاني عشر من هذه الوحدة", "بالاقتران تنتقل مقاومة المضادّ الحيويّ إلى بكتيريا أخرى."),
  ("b10u2", "الفيروسات والفيرويدات والبريونات — أحياء العاشر", "الفيروس آكل البكتيريا في النقل هو نفسه الذي درست دورتيه الحالّة والاندماجية.")], 12)

seg(11, 2, 9, "kzrel", "علاقات البكتيريا وفوائدها وأضرارها",
 "تُكوّن البكتيريا <b>علاقات تكافلية</b> مع الكائنات الأخرى لضمان بقائها ، وهي ثلاثة أنماط :\n"
 "<b>تقايض</b> ( منفعة للطرفين ) : <b>الرايزوبيوم</b> في <b>العقد الجذرية للبقوليات</b> ( الشكل ( 11 ) ) تُثبّت النيتروجين للنبات ، والنبات يُزوّدها بالغذاء والمأوى.\n"
 "<b>تعايش</b> : تعيش على أجسام كائنات <b>من دون أذًى</b>.\n"
 "<b>تطفّل</b> : تُسبّب الأمراض ، مثل <b>السالمونيلا</b>.\n"
 "<b>فوائدها</b> : تحليل المخلّفات العضوية وبقايا الكائنات الميتة وإعادة المواد إلى التربة · <b>بكتيريا القولون</b> في الأمعاء ( الشكل ( 12 ) ) تساعد على الهضم وتُنتج <b>فيتامين " + L("K") + " وفيتامين " + L("H") + " ( البيوتين )</b> · تحليل البقع النفطية ومعالجة مياه التصريف · <b>المعالجة الحيوية</b> بإنزيمات تفكّك الروابط في السلاسل الكربونية.\n"
 "<b>أضرارها</b> : للإنسان : الكزاز ، وحُمّى التيفوئيد ، والالتهاب الرئويّ ، والزهريّ ، والكوليرا · للماشية : الجمرة الخبيثة · للنباتات ( الشكل ( 13 ) ) : تبقّع الأوراق ، واللفحة النارية ، والذبول البكتيريّ ، وسلّ الزيتون.\n"
 "ومن الجدول ( 1 ) : <b>حبّ الشباب</b> ببكتيريا " + L("Cutibacterium acnes") + " وسببه إفراز الدهون الزائد وانسداد بصيلات الشعر ، و<b>الكزاز</b> ببكتيريا " + L("Clostridium tetani") + " وسببه تلوّث الجرح ، ومن أعراضه تشنّجات عضلية شديدة وتصلّب عضلات الفكّ.",
 "لا تخلط الأنماط : <b>التقايض</b> منفعة متبادلة ( الرايزوبيوم ) ، و<b>التعايش</b> بلا أذًى ، و<b>التطفّل</b> يُسبّب المرض ( السالمونيلا ) . ولا تجعل البكتيريا ضارّة كلّها ؛ فبكتيريا القولون في أمعائك تُنتج لك فيتامينات.",
 "حدّد نوع العلاقة ، وما يأخذه كلّ طرف : الرايزوبيوم مع نبات الفول.",
 "<b>العلاقة</b> : تقايض.\n<b>الرايزوبيوم يُعطي</b> : تثبيت النيتروجين للنبات.\n<b>النبات يُعطي</b> : الغذاء والمأوى في العقد الجذرية.",
 "علاقات البكتيريا كعلاقات <b>السكّان في عمارة</b> : شريكان في محلّ يربح كلاهما ( تقايض ) ، وجار هادئ لا يضرّ ولا ينفع ( تعايش ) ، ولصّ يعيش على حساب غيره ( تطفّل ).",
 "يُبنى على المقطع العاشر : الصفات التي تكتسبها البكتيريا تحدّد أثرها في من حولها.",
 [("b10u3", "المقطع الثاني عشر من هذه الوحدة", "الضرر يتضاعف حين تقاوم البكتيريا المضادّ الحيويّ."),
  ("b10u3", "المقطع الثامن عشر من هذه الوحدة", "الأنماط الثلاثة نفسها ستراها في الفطريات : الأشنات والمايكورايزا وصدأ القمح.")], 12)

seg(12, 2, 10, "kzres", "مقاومة المضادات الحيوية : الأدلّة والأرقام",
 "تحدث المقاومة حين <b>تتغيّر البكتيريا استجابةً للتكيّف مع الأدوية</b> ، فتظهر <b>سلالات جديدة مُقاوِمة</b> تُسبّب أمراضًا <b>يطول علاجها</b> . و<b>إساءة استعمال المضادات والإفراط في تناولها يُسرّعان المقاومة</b>.\n"
 "<b>طرائق المقاومة الأربع</b> ( الشكل ( 14 ) ) : <b>إفراز إنزيمات</b> تحطّم المضادّ قبل أن يؤثّر · <b>نقل جزء المقاومة بالاقتران</b> إلى بكتيريا أخرى · <b>تغيير الموقع ( المُستقبِل )</b> الذي يعمل عليه المضادّ · <b>طرد المضادّ إلى الخارج</b>.\n"
 "<b>أدلّة الخطر من البيانات</b> ( تحليل البيانات ص 55 ) : الوفيات المتوقّعة سنويًّا حتّى 2050 م : <b>آسيا 4.7 ملايين</b> · إفريقيا 4.2 ملايين · أمريكا اللاتينية 392 ألفًا · أوروبا 390 ألفًا · أمريكا الشمالية 317 ألفًا · أستراليا 22 ألفًا.\n"
 "المجموع المتوقّع <b>عشرة ملايين</b> عام 2050 م ، وهو <b>أكبر من وفيات السرطان الحالية ( 8.2 ملايين )</b> ، بعد أن كان <b>700000 على الأقلّ عام 2016 م</b>.\n"
 "<b>كيف تقرأ البيانات دليلًا</b> : قارن 700 ألف بعشرة ملايين ( زيادة نحو أربعة عشر ضعفًا ) ، وقارن الرقم بمرض معروف الخطر كالسرطان ، ولاحظ أنّ القارّتين الأكثر سكّانًا تحملان أكثر الوفيات.\n"
 "والدرس العمليّ : <b>لا تتناول المضادّ الحيويّ إلّا بوصفة ، وأكمل الجرعة</b> ؛ لأنّ الإفراط والإساءة يُسرّعان ظهور السلالات المقاوِمة.",
 "لا تقل إنّ <b>الإنسان</b> هو الذي يُصبح مقاومًا للمضادّ ؛ المقاوِمة هي <b>البكتيريا</b> . ولا تقرأ الرقم وحده ؛ الدليل في <b>المقارنة</b> : بعام 2016 م ، وبوفيات السرطان.",
 "استعمل بيانات الكتاب لإثبات أنّ البكتيريا المقاوِمة خطر متزايد بدليلين رقميّين.",
 "<b>الدليل الأوّل ( التزايد )</b> : الوفيات 700000 على الأقلّ عام 2016 م ، والمتوقّع عشرة ملايين عام 2050 م ، أي نحو أربعة عشر ضعفًا.\n<b>الدليل الثاني ( المقارنة )</b> : عشرة ملايين أكبر من وفيات السرطان الحالية ( 8.2 ملايين ).\n<b>دليل مساند</b> : آسيا وحدها 4.7 ملايين سنويًّا.",
 "المقاومة كـ<b>لصّ يتعلّم فتح الأقفال</b> : كلّ مرّة تستعمل فيها القفل نفسه بلا داعٍ ( الإفراط في المضادّ ) تمنحه فرصة للتدرّب ، فيظهر لصوص لا يوقفهم القفل ، ويتعلّم منهم غيرهم ( الاقتران ).",
 "يُبنى على المقطع العاشر : الاقتران إحدى طرائق نشر المقاومة.",
 [("b10u1", "نظرية التطوّر — أحياء العاشر", "ظهور سلالات مقاوِمة مثال على الانتخاب الطبيعيّ الذي درسته."),
  ("b10u3", "المقطع الثامن عشر من هذه الوحدة", "المضادّ الحيويّ البنسلين يُنتجه فطر البنيسيليوم.")], 12)

seg(13, 3, 11, "kzalgae", "الطلائعيات ومجموعاتها الثلاث ، والطحالب",
 "<b>الطلائعيات</b> " + L("Protists") + " : كائنات <b>حقيقية النَّوى</b> ، <b>معظمها وحيد الخلية</b> ومنها عديد الخلايا ، فيها عضيّات مختلفة ، وتعيش في المياه العذبة والمالحة وفي البيئات الرطبة على اليابسة . وتُصنَّف بحسب <b>طريقة التغذية</b> إلى ثلاث مجموعات :\n"
 "<b>الشبيهة بالنباتات ( الطحالب )</b> : ذاتية التغذية لاحتوائها <b>الكلوروفيل</b> فتقوم بالبناء الضوئيّ.\n"
 "<b>الشبيهة بالحيوانات ( الأوليات )</b> : تتغذّى بكائنات أخرى ، ولا أجهزة متخصّصة فيها.\n"
 "<b>الشبيهة بالفطريات</b> : غير ذاتية التغذية ، تحلّل المواد العضوية ، لكنّ جدارها من <b>السليلوز</b>.\n"
 "<b>الطحالب وصبغاتها</b> ( الأشكال ( 15 ) إلى ( 20 ) ) ، واللون الظاهر لون الصبغة الغالبة :\n"
 "<b>الخضراء</b> : كلوروفيل " + L("a") + " و " + L("b") + " وكاروتينويدات ، وحيدة أو عديدة الخلايا · <b>اليوغلينات</b> : كلوروفيل " + L("a") + " و " + L("b") + " وكاروتينويدات ، وحيدة الخلية · <b>الدياتومات</b> : كلوروفيل " + L("a") + " و " + L("c") + " وكاروتينويدات ، وحيدة الخلية · <b>الحمراء</b> : كلوروفيل " + L("a") + " و<b>الفايكوإريثرين</b> ، عديدة الخلايا · <b>البنّية</b> : كلوروفيل " + L("a") + " و " + L("c") + " و<b>الفيوكوزانثين</b> ، عديدة الخلايا وتضمّ أعشاب البحر.\n"
 "وللتصنيف سؤال واحد أوّلًا : <b>كيف يحصل على غذائه ؟</b> يصنعه ← طحلب . يلتهم كائنات ← أوليات . يُحلّل المواد العضوية ← شبيه بالفطريات.",
 "لا تعدّ الطلائعيات كلّها وحيدة الخلية ؛ <b>معظمها</b> فقط . ولا تعدّ <b>اليوغلينا</b> من الأوليات ؛ فهي ذاتية التغذية من <b>الطحالب</b> . و<b>الفايكوإريثرين في الحمراء</b> و<b>الفيوكوزانثين في البنّية</b> ، لا العكس.",
 "فسّر : تمتاز الطلائعيات الشبيهة بالنباتات بألوان عدّة.",
 "<b>السبب</b> : تختلف في أنواع الصبغات ، واللون الظاهر لون الصبغة الغالبة.\n<b>الخضراء</b> : كلوروفيل " + L("a") + " و " + L("b") + " ← أخضر.\n<b>الحمراء</b> : الفايكوإريثرين ← أحمر.\n<b>البنّية</b> : الفيوكوزانثين ← بنّيّ.",
 "الطلائعيات <b>« درج المتفرّقات »</b> في خزانة حقيقيات النَّوى : ما ليس نباتًا ولا حيوانًا ولا فطرًا تامًّا يوضع فيه ، ثمّ يُفرز الدرج بحسب طريقة الأكل : من يطبخ طعامه ، ومن يأكل غيره ، ومن يعيش على البقايا.",
 "يُبنى على المقطع الخامس : الطلائعيات إحدى الممالك الأربع في نطاق حقيقيات النَّوى.",
 [("b10u3", "المقطع الرابع عشر من هذه الوحدة", "الأوليات تُفرز من جديد ، لكن بمعيار الحركة هذه المرّة."),
  ("b9u2", "الخليّة وعمليّاتها الحيويّة — أحياء التاسع", "البناء الضوئيّ في البلاستيدات الخضراء هو ما يجعل الطحالب ذاتية التغذية.")], 12)

seg(14, 3, 11, "kzmove", "الأوليات بوسائل حركتها ، والشبيهة بالفطريات",
 "صُنّفت <b>الأوليات</b> بحسب <b>وسيلة الحركة</b> إلى أربع مجموعات ( الشكل ( 21 ) ) :\n"
 "<b>الهدبيات</b> : بـ<b>الأهداب</b> ، تدفع الجسم وتساعد في التغذية ، ومنها <b>البراميسيوم</b> ( الشكل ( 22 ) ) : أهداب تغطّي جسمه كلّه ، ونواتان : <b>كبيرة</b> للعمليات الحيوية و<b>صغيرة</b> للتكاثر ، وفجوات غذائية وفجوة منقبضة وتجويف فمويّ.\n"
 "<b>جذريات القدم</b> : بـ<b>الأقدام الكاذبة</b> ( بروزات مؤقّتة ) ، تتحرّك بها وتحصل بها على الغذاء بـ<b>البلعمة</b> ( الشكل ( 24 ) ) : تحيط الأقدام بالطعام ، فيُهضم بمساعدة <b>اللايسوسوم</b> مكوّنًا جسمًا حالًّا ، ثمّ يُمتصّ وتُطرح الفضلات . ومثالها <b>الأميبا</b> ( الشكل ( 25 ) ).\n"
 "<b>البوغيات</b> : <b>لا تراكيب للحركة</b> فيها ، فتنزلق مع سوائل جسم العائل ، مثل <b>البلازموديوم</b>.\n"
 "<b>السوطيات الحيوانية</b> : بـ<b>الأسواط</b> ( واحد أو أكثر ) ، مثل الليشمانيا والجيارديا.\n"
 "<b>الشبيهة بالفطريات</b> : <b>الفطريات المائية</b> ( الشكل ( 29 ) ) في المياه والأماكن الرطبة ، ومنها ما يتطفّل على خياشيم الأسماك وجلودها ، و<b>الفطريات الغروية</b> ( الشكل ( 30 ) ) في التربة الرطبة وبخاصّة تربة الغابات . وتُشبه الفطريات في التغذية ، وتختلف عنها في الجدار : <b>سليلوز لا كايتين</b>.",
 "لا تخلط <b>معيار الطلائعيات</b> ( التغذية ) بـ<b>معيار الأوليات</b> داخلها ( الحركة ) . ولا تجعل البلازموديوم من السوطيات ؛ فهو من <b>البوغيات</b> بلا تراكيب حركة . وجدار الشبيهة بالفطريات <b>سليلوز</b> ، وهذا أهمّ ما يميّزها عن الفطريات.",
 "صنّف الطلائعيات الآتية إلى مجموعاتها ، مع ذكر المعيار : البراميسيوم ، اليوغلينا ، البلازموديوم ، الأميبا ، الليشمانيا.",
 "<b>البراميسيوم</b> : أوليات ، هدبيات ( الأهداب ).\n<b>اليوغلينا</b> : شبيهة بالنباتات ( ذاتية التغذية ).\n<b>البلازموديوم</b> : أوليات ، بوغيات ( الانزلاق ).\n<b>الأميبا</b> : أوليات ، جذريات القدم ( الأقدام الكاذبة ).\n<b>الليشمانيا</b> : أوليات ، سوطيات حيوانية ( الأسواط ).",
 "تخيّل <b>أربعة سبّاحين</b> : واحد يجدّف بآلاف المجاديف الصغيرة ( الأهداب ) ، وآخر يمدّ ذراعًا من جسمه ويسحب نفسه ( القدم الكاذبة ) ، وثالث يدفعه سوط في ذيله ( السوط ) ، ورابع لا يسبح أبدًا بل يحمله التيّار ( البوغيات ).",
 "يُبنى على المقطع الثالث عشر : الأوليات إحدى المجموعات الثلاث ، وهنا تفرز بالحركة.",
 [("b10u3", "المقطع الخامس عشر من هذه الوحدة", "أمثلة المجموعات الأربع هي نفسها مسبّبات الأمراض : الزحار والملاريا والليشمانيا."),
  ("b9u2", "الخليّة وعمليّاتها الحيويّة — أحياء التاسع", "اللايسوسوم ( الجسم الحالّ ) الذي يهضم الطعام في الأميبا عضيّ درسته هناك.")], 12)

seg(15, 3, 12, "kzprot", "أثر الطلائعيات في الكائنات والإنسان",
 "<b>الأثر النافع : الطحالب</b> : هي <b>المُنتِج الأساسيّ</b> في السلسلة الغذائية في البحار والمحيطات ، يتغذّى بها كثير من الأسماك الصغيرة والعوالق · تُنتج <b>الأكسجين</b> لتنفّس الكائنات المائية ، فأهمّيتها في الماء كأهمّية النباتات على اليابسة · تُنتج الكربوهيدرات والدهون ، وتُستخدم أنواع منها تجاريًّا في إنتاج البروتينات والدهون والكربوهيدرات والفيتامينات.\n"
 "<b>الأثر الضارّ : أمراض الأوليات</b> :\n"
 "<b>الزحار البالانتيديوميّ</b> : <b>البالانتيديوم كولاي</b> ( هدبيات ، الشكل ( 23 ) ) ← إسهال يخالطه الدم والمخاط.\n"
 "<b>الزحار الأميبيّ</b> : <b>الإنتاميبا هيستوليتيكا</b> ( جذريات القدم ، الشكل ( 26 ) ) ← إسهال شديد يخالطه الدم والمخاط.\n"
 "<b>الملاريا</b> : <b>البلازموديوم</b> ( بوغيات ) ← ينتقل بلدغة <b>أنثى بعوضة الأنوفلس</b> ( الشكل ( 27 ) ).\n"
 "<b>الليشمانيا الجلدية</b> : <b>الليشمانيا</b> ( سوطيات ) ← تنتقل بـ<b>ذبابة الرمل</b> ( الشكل ( 28 ) ).\n"
 "<b>الجيارديا ( حُمّى القُندُس )</b> : عدوى معوية بالجيارديا ( سوطيات ).\n"
 "والشبيهة بالفطريات قد تتطفّل على <b>خياشيم الأسماك وجلودها</b>.\n"
 "<b>تحليل بيانات الليشمانيا</b> ( مراجعة الدرس ) : الفئة العمرية <b>من سنة إلى سنتين</b> هي الأكثر إصابة ( 96 عام 2007 م ) ، والإصابات انخفضت عام 2008 م ، والذكور أكثر من الإناث في العامين ( 120 مقابل 110 ، ثمّ 89 مقابل 69 ) . وتفسير الأرقام فرضيات تُصاغ بحذر ، لا حقائق من الكتاب.",
 "لا تخلط <b>الزحار الأميبيّ</b> ( الإنتاميبا ، جذريات القدم ) بـ<b>الزحار البالانتيديوميّ</b> ( البالانتيديوم ، هدبيات ) . وناقل الملاريا <b>أنثى</b> بعوضة الأنوفلس ، وناقل الليشمانيا <b>ذبابة الرمل</b> ، لا العكس.",
 "قيّم العبارة : « الطلائعيات ضارّة بالإنسان » ، بدليلين من الكتاب على كلّ جانب.",
 "<b>العبارة غير دقيقة</b> ؛ ففي الطلائعيات نافع وضارّ.\n<b>نافع</b> : الطحالب المُنتِج الأساسيّ في السلسلة الغذائية البحرية ، وتُنتج الأكسجين للكائنات المائية.\n<b>ضارّ</b> : البلازموديوم يُسبّب الملاريا ، والإنتاميبا تُسبّب الزحار الأميبيّ.",
 "الطلائعيات في البحر كـ<b>مخبز المدينة</b> : يُطعم الجميع ويملأ الجوّ بما يُتنفَّس ( الطحالب ) ، وفي الشارع نفسه <b>لصوص صغار</b> يدخلون الأجسام فيُمرضونها ( الأوليات المتطفّلة ).",
 "يُبنى على المقطع الرابع عشر : أمثلة الأوليات بحسب الحركة هي مسبّبات هذه الأمراض.",
 [("b10u3", "المقطع السادس عشر من هذه الوحدة", "الدرس الرابع ينتقل إلى الفطريات : جدار من الكايتين وتغذية امتصاصية."),
  ("b9u1", "دراسة الحياة — أحياء التاسع", "صياغة الفرضيات من البيانات خطوة من خطوات الطريقة العلمية.")], 12)

seg(16, 4, 13, "kzfungi", "الفطريات : التركيب والتغذية والتكاثر",
 "<b>الفطريات</b> " + L("Fungi") + " : حقيقية النَّوى ، <b>معظمها عديد الخلايا إلّا الخمائر</b> فوحيدة الخلية ، وجُدُرها من <b>الكايتين</b> " + L("Chitin") + " ( مركّب عديد السكّريات يُشبه السليلوز ).\n"
 "<b>التركيب</b> ( الشكل ( 31 ) ) : <b>خيوط فطرية</b> " + L("Hyphae") + " تتجمّع في <b>غزل فطريّ</b> " + L("Mycelium") + " . والخيوط إمّا <b>مقسّمة بحواجز خلوية</b> " + L("Septa") + " ، وإمّا بلا حواجز وتُسمّى <b>المدمج الخلويّ</b> " + L("Coenocytes") + " . وفي عفن الخبز : <b>أشباه جذور</b> تثبّته وتمتصّ ، و<b>حامل</b> في نهايته <b>كيس بوغيّ</b> فيه الأبواغ.\n"
 "<b>التغذية</b> : <b>غير ذاتية</b> ؛ تُفرز <b>إنزيمات هاضمة خارج خلاياها</b> على الغذاء ، ثمّ <b>تمتصّ</b> المواد المهضومة عبر جدرها . وأنواعها ثلاثة : <b>رمّية</b> من المخلّفات والكائنات غير الحيّة ( المشروم ) · <b>طفيلية</b> على كائنات حيّة فتُمرضها ( صدأ القمح ) · <b>تقايضية</b> ( الأشنات : فطر وطحلب ).\n"
 "<b>التكاثر</b> : <b>لاجنسيّ</b> بآلاف <b>الأبواغ</b> أحادية المجموعة " + L("1n") + " تنمو عند توفّر الحرارة والرطوبة والمواد العضوية ، ومنه <b>التبرعم</b> في الخمائر ( الشكل ( 36 ) ) · <b>جنسيّ</b> : تتّحد نواتا خيطين ( الشكل ( 37 ) ) فتنتج نواة <b>" + L("2n") + "</b> تنقسم <b>انقسامًا منصّفًا</b> فتُنتج أبواغًا <b>" + L("1n") + "</b>.",
 "لا تعدّ الفطريات ذاتية التغذية ولا آكلة ؛ هي <b>تهضم خارج خلاياها ثمّ تمتصّ</b> . ولا تخلط <b>الحواجز</b> بـ<b>المدمج الخلويّ</b> ( بلا حواجز ) . والنواة " + L("2n") + " في التكاثر الجنسيّ <b>تنقسم منصّفًا</b> فتُنتج أبواغًا " + L("1n") + " لا " + L("2n") + ".",
 "وضّح كيف تحصل الفطريات على غذائها ، واذكر مثالًا لكلّ نوع من أنواع تغذيتها.",
 "<b>الطريقة</b> : تُفرز إنزيمات هاضمة خارج خلاياها على مصدر الغذاء ، فتتحلّل المواد العضوية ، ثمّ تمتصّها عبر جدرها الخلوية.\n<b>رمّية</b> : المشروم · <b>طفيلية</b> : صدأ القمح · <b>تقايضية</b> : الأشنات.",
 "الفطر كـ<b>شبكة أنابيب تحت الأرض</b> ( الغزل الفطريّ ) تسكب العصارة الهاضمة على الطعام ثمّ تشفطه مهضومًا . والمشروم الذي تراه فوق الأرض جزء صغير من الشبكة.",
 "يُبنى على المقطع الرابع عشر : الشبيهة بالفطريات تُشبهها في التغذية وتختلف في الجدار.",
 [("b10u3", "المقطع السابع عشر من هذه الوحدة", "بعد الخصائص العامّة : المجموعات الخمس بأمثلتها."),
  ("b9u2", "الخليّة وعمليّاتها الحيويّة — أحياء التاسع", "الانقسام المنصّف الذي يُنتج الأبواغ أحادية المجموعة درسته هناك.")], 12)

seg(17, 4, 13, "kzfgroup", "مجموعات الفطريات الخمس",
 "تُصنَّف الفطريات إلى مجموعات ، منها خمس في الكتاب :\n"
 "<b>الأصيصية</b> " + L("Chytridiomycota") + " : <b>أبسطها تركيبًا</b> ، معظمها في الماء ، و<b>أبواغها تتحرّك بالأسواط</b> ، رمّية أو متطفّلة ، ويُعتقد أنّها سبب <b>تناقص البرمائيات</b> ومنها الضفادع ( الشكل ( 38 ) ).\n"
 "<b>الاقترانية ( الزيجوتية )</b> " + L("Zygomycota") + " : معظمها رمّيّ ، وبعضها يتطفّل على النباتات و<b>الحشرات</b> ( الشكل ( 39 ) ) ، ومنها <b>عفن الخبز</b> بخيوط مدمجة خلويًّا.\n"
 "<b>الكبيبية</b> " + L("Glomeromycota") + " : تعيش على <b>جذور النباتات</b> تكافليًّا ( <b>المايكورايزا</b> ) ، وتُحسّن امتصاص الماء والأملاح.\n"
 "<b>الكيسية</b> " + L("Ascomycota") + " : <b>أكبر المجموعات</b> ، مهمّة في الصناعات الغذائية ، ومنها <b>الخمائر</b> و<b>الكمأ</b> ( الشكل ( 41 ) ) ، وبعضها يُسبّب <b>البياض الدقيقيّ</b> في العنب و<b>قدم الرياضيّ</b> في الإنسان.\n"
 "<b>القمعية</b> " + L("Basidiomycota") + " : واسعة الانتشار ، رمّية ، متباينة الحجوم والألوان ، ومنها <b>المشروم</b> ( الشكل ( 43 ) ) ، وبعض أنواعه <b>سامّة</b> رغم جمال مظهرها.\n"
 "ومقارنة الكتاب : <b>عفن الخبز</b> اقترانيّ ، خيوطه مدمجة خلويًّا ، وأجزاؤه أشباه الجذور والحامل والكيس البوغيّ · <b>المشروم</b> قمعيّ ، خيوطه مقسّمة بحواجز ، وأجزاؤه الغزل تحت التربة والساق والقبّعة.",
 "لا تضع <b>الكمأ</b> مع <b>المشروم</b> ؛ فالكمأ <b>كيسيّ</b> والمشروم <b>قمعيّ</b> . والتي <b>أبواغها تتحرّك بالأسواط</b> هي الأصيصية وحدها . ولا تعدّ كلّ مشروم صالحًا للأكل.",
 "قارن بين عفن الخبز وفطر المشروم من حيث : المجموعة ، ونوع الخيوط ، والأجزاء الرئيسة.",
 "<b>عفن الخبز</b> : الاقترانية · خيوط مدمجة خلويًّا بلا حواجز · أشباه جذور وحامل وكيس بوغيّ.\n<b>المشروم</b> : القمعية · خيوط مقسّمة بحواجز · غزل تحت التربة وساق وقبّعة.\n<b>الاتفاق</b> : غير ذاتيّ التغذية ، وجداره من الكايتين ، ويعيش رمّيًّا.",
 "احفظ المجموعات بـ<b>علامة مميّزة</b> لكلّ منها : الأصيصية « السبّاحة » ( أبواغ بأسواط ) ، والاقترانية « عفن الخبز » ، والكبيبية « صديقة الجذور » ، والكيسية « الأكبر : خميرة وكمأ » ، والقمعية « المشروم ».",
 "يُبنى على المقطع السادس عشر : الخصائص العامّة ، وهنا ما يميّز كلّ مجموعة.",
 [("b10u3", "المقطع الثامن عشر من هذه الوحدة", "أهمّية هذه المجموعات وأضرارها في الاقتصاد والبيئة."),
  ("b10u1", "نظرية التطوّر — أحياء العاشر", "تناقص البرمائيات بالفطريات الأصيصية مثال على أثر البيئة في بقاء الأنواع.")], 12)

seg(18, 4, 14, "kzfimp", "الفطريات : علاقاتها وأهمّيتها وتهديدها للاقتصاد",
 "<b>علاقات الفطريات بغيرها</b> :\n"
 "<b>تقايض</b> : <b>الأشنات</b> ( الشكل ( 34 ) ) : الفطر يُزوّد الطحلب بالماء والأملاح من الصخور أو الأشجار ، والطحلب يمدّ الفطر بالغذاء بالبناء الضوئيّ · <b>المايكورايزا</b> ( الشكل ( 40 ) ) : تُحسّن امتصاص الجذور للماء والأملاح.\n"
 "<b>تطفّل</b> : صدأ القمح ( الشكل ( 33 ) ) ، والاقترانية على الحشرات ، والبياض الدقيقيّ ، وقدم الرياضيّ ( الشكل ( 42 ) ).\n"
 "<b>الأهمّية</b> ( جدول ص 73 ) : <b>بيئية</b> : المشروم يحلّل المواد العضوية ، والأشنات تفتّت الصخور فتزيد خصوبة التربة ، وفطر المحار ( الشكل ( 32 ) ) في المعالجة الحيوية · <b>طبّية وزراعية</b> : <b>البنيسيليوم</b> يُنتج <b>البنسلين</b> ( الشكل ( 35 ) ) ، ومركّبات للمكافحة الحيوية · <b>اقتصادية</b> : المشروم والكمأ غذاء ، وخميرة الخبز ، ومزارع ومصانع وغاز حيويّ · <b>رؤى مستقبلية</b> : مركّبات بالهندسة الجينية ، والسيطرة على تلوّث النفط والمواد المشعّة ، ومواد مضادّة للسرطان والفيروسات.\n"
 "<b>أدلّة تهديد الاقتصاد الوطنيّ</b> : <b>الأسكدنيا</b> مصدر دخل مهمّ لمزارعي <b>راجب في لواء كفرنجة بعجلون</b> ، تُزرع في نحو <b>ألف دونم</b> ، وتعرّضت لأضرار كبيرة بالفطريات والآفات فخسر المزارعون خسائر مادية كبيرة · و<b>صدأ القمح</b> يُلحق خسائر كبيرة بالاقتصاد.\n"
 "ولبناء دليل اقتصاديّ اذكر ثلاثة : <b>المحصول ومكانه</b> ، و<b>حجمه</b> ( ألف دونم ) ، و<b>الضرر</b> ( خسائر للمزارعين ).",
 "لا تنسب البنسلين إلى المشروم ؛ يُنتجه فطر <b>البنيسيليوم</b> . ولا تعدّ الأشنات كائنًا واحدًا ؛ هي <b>علاقة تقايض بين فطر وطحلب</b> . والمايكورايزا علاقة <b>تقايض</b> لا تطفّل.",
 "ما العلاقة بين اختفاء الأشنات ومستوى خصوبة التربة في الغابات ؟",
 "<b>المعطى</b> : الأشنات تقايض بين فطر وطحلب ، وتفتّت الصخور التي تنمو عليها.\n<b>القاعدة</b> : تفتيت الصخور يُحرّر الأملاح ويُسهم في تكوين التربة وزيادة خصوبتها.\n<b>الاستنتاج</b> : اختفاء الأشنات يُبطئ تفتيت الصخور ، فتقلّ العناصر المضافة إلى التربة وتنخفض خصوبتها.",
 "الفطريات <b>سكّين ذو حدّين</b> : الحدّ النافع يصنع الخبز والدواء ويُخصب التربة ، والحدّ الضارّ يأكل القمح والأسكدنيا ويُصيب الجلد . والسؤال دائمًا : أيّ الحدّين في هذا المثال ؟ وما نوع العلاقة ؟",
 "يُبنى على المقطع السابع عشر : المجموعات نفسها ، وهنا أثرها.",
 [("b10u3", "المقطع الحادي عشر من هذه الوحدة", "قارن علاقات الفطريات بعلاقات البكتيريا : تقايض وتعايش وتطفّل."),
  ("e10u1", "الصخور — علوم الأرض العاشر", "تفتيت الأشنات للصخور من صور التجوية التي تُكوّن التربة.")], 12)

